def max_sum_list(lists):
    if not lists:
        return []
    max_sum = sum(lists[0])
    max_list = lists[0]
    for lst in lists[1:]:
        current_sum = sum(lst)
        if current_sum > max_sum:
            max_sum = current_sum
            max_list = lst
    return max_list
